export function exportReport(p){const report=['✓ Exports Quickshell panels, Widget Neighborhood compositions, component files, live-data adapter, wallpaper, uploaded fonts and a copy of your .rce project.','✓ Live clock, workspace switching, volume, music, battery, CPU and RAM. Network/Bluetooth status and notification count need the listed services.','✓ Pulse, float, rotate, glow, slide and fade animations export to Quickshell with bounded timing.','↗ Network/Bluetooth/notification settings open their installed native applications. They are not replicas of the browser preview panels.','⚠ Background blur is preview-only in this export. Shadow and borders are exported; panel shadows may clip at native window edges.','⚠ Standalone Quickshell export preserves desktop key bindings in .rce. Full Rice export installs reviewed allowlisted bindings and Hyprland rules.','⚠ The browser uses sample data. The exported shell reports unavailable services instead of displaying fake live values.'];if(p.elements.some(e=>!e.parentId&&e.reveal?.mode==='hot-edge'))report.push('✓ Left and right hot-edge panels export as Quickshell Overlay windows above applications and do not reserve workspace space.');if(p.elements.some(e=>e.options?.items?.length&&!['bar','dock','widget'].includes(e.type)))report.push('⚠ Legacy custom items on standalone widgets can overlap the main widget text; use a Dock, Bar or Custom Widget for exported shortcuts.');if(unresolved(p).length)report.push('⚠ Unlinked shortcuts: '+unresolved(p).join(', '));if(desktop(p).mode==='live')report.push('✓ Live wallpaper video is bundled. Native playback requires mpvpaper; missing mpvpaper produces a visible terminal warning and a solid fallback.');if(desktop(p).mode==='gradient')report.push('⚠ Gradient angles export as horizontal or vertical; arbitrary angles are preview-only.');if(p.elements.some(e=>e.options?.align==='space-between'))report.push('⚠ space-between custom shortcut layout exports as a centered group with its configured gap.');return report;}
