export function buildFiles(p,templates){validate(p);const files={'shell.qml':qml(p),'Widget.qml':templates.widget,'PowerMenu.qml':powerMenuQml,'bridge.py':templates.bridge,'audio_engine.py':templates.audioEngine||'','project.rce':serialize(p),'manifest.json':JSON.stringify({format:'ricing-town-quickshell',version:2,quickshell:'0.3.1',audioEngine:'CAVA PipeWire with built-in FFT fallback',warnings:exportReport(p)},null,2)};const d=desktop(p);if(d.image)files['wallpaper.'+d.image.match(/^data:image\/(\w+)/)[1]]=decodeData(d.image);const liveMatch=d.video.match(/^data:video\/(mp4|webm)/);if(liveMatch)files['live-wallpaper.'+liveMatch[1]]=decodeData(d.video);let fontIndex=0,iconIndex=0,audioIndex=0;for(const a of (p.assets||[])){if(a.extension==='svg')files[`icons/${iconIndex++}.svg`]=a.data;else if(['ttf','otf'].includes(a.extension))files[`fonts/${fontIndex++}.${a.extension}`]=decodeData(a.data);else if(['mp3','ogg','wav','flac','m4a'].includes(a.extension))files[`audio/${audioIndex++}.${a.extension}`]=decodeData(a.data);}
 const alignX=d.position==='left'?-1:d.position==='right'?1:0,alignY=d.position==='top'?-1:d.position==='bottom'?1:0,videoOptions=[d.videoMuted?'--no-audio':'',d.fit==='cover'?'--panscan=1.0':d.fit==='stretch'?'--video-aspect-override=-1':'--panscan=0.0',`--video-align-x=${alignX}`,`--video-align-y=${alignY}`,'--loop-file=inf'].filter(Boolean).join(' ');files['start.sh']=`#!/bin/sh\nset -eu\ncd -- "$(dirname -- "$0")"\ncommand -v qs >/dev/null || { echo "Install Quickshell 0.3.1"; exit 1; }\ncommand -v python3 >/dev/null || { echo "Install Python 3"; exit 1; }\nwallpaper_pid=\ncleanup(){ if [ -n "$wallpaper_pid" ]; then kill "$wallpaper_pid" 2>/dev/null || true; fi; }\ntrap cleanup EXIT INT TERM\n${liveMatch?`if command -v mpvpaper >/dev/null; then mpvpaper -o ${JSON.stringify(videoOptions)} '*' "$PWD/live-wallpaper.${liveMatch[1]}" & wallpaper_pid=$!; else echo "Live wallpaper unavailable: install mpvpaper" >&2; fi`:''}\nqs -p "$PWD/shell.qml" &\nshell_pid=$!\nwait "$shell_pid"\n`;
 files['REQUIREMENTS.md']=`# Ricing Town exported shell\n\nRequires Linux/Wayland, Hyprland, Quickshell 0.3.1, QtQuick Controls and QtQuick Effects, Python 3. Live video wallpapers additionally require mpvpaper; the shell continues with a solid fallback when it is unavailable. Music spectrum widgets use CAVA with PipeWire for accurate smoothed stereo bands. Install cava for the recommended engine; pw-cat is required only for the built-in FFT fallback.\n\nOptional live integrations: mpv for bundled local tracks; wpctl (WirePlumber) for audio; playerctl and an MPRIS player for music; NetworkManager/nmcli and nm-connection-editor for networking; BlueZ/bluetoothctl and blueman-manager for Bluetooth; swaync and swaync-client for notifications; hyprlock for lock; systemd/logind (systemctl) and session authorization for Sleep, Restart and Shut down. The fullscreen power menu asks for a second click before these three actions; Cancel, Back and Escape do not run commands. App shortcuts require the selected applications (Kitty, Firefox, Thunar, pavucontrol or Qalculate). Missing dependencies produce unavailable states or action errors, never simulated values. CPU/RAM use Linux /proc and battery uses /sys.\n\n## Apply without replacing your existing config\n1. Extract the ZIP to a permanent folder. Keep your existing .rce and Hyprland configuration backed up.\n2. Open a terminal in that folder and run: sh start.sh\n3. Inspect the result before adding autostart. Stop it with Ctrl+C in that terminal. Nothing is copied into your Hyprland configuration automatically.\n4. For autostart choose exactly ONE snippet matching your Hyprland version, replacing /absolute/path with the extracted folder's absolute path. Do not mix the Lua and legacy snippets.\n\n## Restore\nStop the process launched by start.sh with Ctrl+C. If you added autostart, remove only that added line and stop this shell instance. Existing compositor configuration and previous wallpaper files were not overwritten. Your original wallpaper service may be kept running beneath this shell; stopping the shell reveals it.\n\n## Appearance and compatibility\n${exportReport(p).join('\n\n')}\n\nGradient angle exports as horizontal or vertical according to its angle (not arbitrary-angle fidelity). Font files uploaded to the project are bundled and loaded locally; system sans/serif/monospace use fonts installed on the target machine and are not copied. Use a font you have permission to redistribute. Application icons are stored text glyphs and depend on the selected font. Panels use screen-relative anchors and clamp to monitor edges. Panels do not reserve workspace space automatically; configure Hyprland gaps/reserved areas separately if needed. All screens receive the same design.\n\n## Browser vs native\nThe browser stays a design/simulation tool and has no privileged live API. bridge.py is a local, fixed-action process adapter launched by Quickshell, not a network service. It does not evaluate arbitrary project commands. A future direct connection from the editor needs a separate authenticated local companion with explicit pairing and an action allowlist; no such HTTP connection is enabled here.\n`;
 files['hyprland-legacy.conf.example']='# Hyprland 0.54 or older: replace the absolute path before use.\nexec-once = sh /absolute/path/start.sh\n';files['hyprland-lua.lua.example']='-- Hyprland 0.55+: replace the absolute path before use.\nhl.exec_cmd("sh /absolute/path/start.sh")\n';return files;}
export async function exportPackage(p){const [widget,bridge,audioEngine]=await Promise.all(['runtime/Widget.qml','runtime/bridge.py','runtime/audio_engine.py'].map(async path=>{const r=await fetch(path);if(!r.ok)throw Error('Export runtime unavailable');return r.text();}));return zip(buildFiles(p,{widget,bridge,audioEngine}));}
